  def safe_click(self, locator, timeout=15):
    wait = WebDriverWait(self.driver, timeout)
    end_time = time.time() + timeout
    while time.time() < end_time:
      try:
        element = wait.until(EC.presence_of_element_located(locator))
        try:
          element.click()
          return element
        except Exception:
          try:
            self.driver.execute_script("var el = arguments[0]; if (el) { (el.closest('[tabindex]') || el.closest('[role=\"button\"]') || el.parentElement || el).click(); }", element)
          except Exception:
            pass
          return element
      except (StaleElementReferenceException, ElementClickInterceptedException, NoSuchElementException):
        time.sleep(0.5)
    raise TimeoutException(f"Failed to click element with locator {locator} within {timeout} seconds.")

  def safe_send_keys(self, locator, keys, timeout=15):
    wait = WebDriverWait(self.driver, timeout)
    end_time = time.time() + timeout
    while time.time() < end_time:
      try:
        element = wait.until(EC.visibility_of_element_located(locator))
        element.click()
        element.send_keys(Keys.CONTROL + "a")
        element.send_keys(Keys.BACKSPACE)
        element.send_keys(keys)
        element.send_keys(Keys.TAB)
        return element
      except (StaleElementReferenceException, ElementClickInterceptedException, NoSuchElementException):
        time.sleep(0.5)
    raise TimeoutException(f"Failed to send keys to element with locator {locator} within {timeout} seconds.")

  def test_login(self):
    self.driver.get("http://localhost:8081/")
    self.driver.set_window_size(1550, 830)
    
    # Clear local storage for clean test isolation
    try:
      self.driver.execute_script("window.localStorage.clear(); window.sessionStorage.clear();")
      self.driver.get("http://localhost:8081/")
    except Exception:
      pass
    
    # 1. Wait for splash screen (1.5s) to finish and click "Sign In" on Welcome screen
    time.sleep(2.0)
    self.safe_click((By.XPATH, "(//*[text()='Sign In' or text()='Sign in'])[1]"))
    time.sleep(1.0)
    
    # 2. Enter email in Email input
    self.safe_send_keys((By.XPATH, "//input[@placeholder='name@example.com' or @type='email']"), "sakthi@autodoc.com")
    
    # 3. Enter password in Password input
    self.safe_send_keys((By.XPATH, "//input[@type='password']"), "autodocpartner2026")
    time.sleep(0.5)
    
    # 4. Click "Sign In" submit button on Login screen
    self.safe_click((By.XPATH, "//div[@role='button'][.//*[text()='Sign In']] | (//*[text()='Sign In'])[last()]"))

    # 5. Verify successful login by waiting for dashboard elements or text to appear
    wait = WebDriverWait(self.driver, 15)
    dashboard_element = wait.until(
      EC.presence_of_element_located((By.XPATH, "//*[contains(text(),'Sakthi') or contains(text(),'Overview') or contains(text(),'Dashboard') or contains(text(),'Sign Out')]"))
    )
    assert dashboard_element is not None, "Login failed or dashboard did not render."

  
